KG42.register("rules-2013473d3b3564f5279926ff",{"id":"20-storage_sharing_auction::v141-c-R003","paper":"20-storage_sharing_auction","record":{"rule_id":"v141-c-R003","mechanism_id":"v141-a-M01","name":"Price-signal coordination","process_stage":"coordination","market_meaning":"The auction price p_t announced by the auctioneer coordinates participating RUs' choices of ES space to share, with each RU choosing within [0, b_i] to maximize its own utility. Scope: The Stackelberg payment rule for joint ES sharing within the smart community, including its application within each time slot.","independence_rationale":"Relations governed by the approved function coordination.price_signal under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["coordination.price_signal","pricing.local"],"E":[{"edge_id":"v141-c-R003-E001","source":"pricing.local","target":"coordination.price_signal","type":"links","constraint_ids":["v141-c-R003-C001"],"evidence_ids":["v141-b-g01-E04","v141-b-g02-E13","v141-b-g02-E17","v141-b-g02-E34"]}],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"The Stackelberg payment rule for joint ES sharing within the smart community, including its application within each time slot.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-E04","v141-b-g02-E13","v141-b-g02-E17","v141-b-g02-E34"]},"x":[{"variable_id":"v141-c-R003-x-p_t","symbol":"p_t","meaning":"Auction price announced by the auctioneer as the price signal for sharing ES, per unit of energy in the source's Stackelberg payment rule.","kind":"operational","domain":"[p_t^{min}, p_t^{max}]","unit":null,"indices":["t"],"evidence_ids":["v141-b-g02-E13","v141-b-g02-E19","v141-b-g01-E36"]},{"variable_id":"v141-c-R003-x-x_i","symbol":"x_i","meaning":"Amount or fraction of ES space that RU i chooses to share in response to the announced auction price p_t.","kind":"operational","domain":"[0, b_i]","unit":null,"indices":["i"],"evidence_ids":["v141-b-g02-E17","v141-b-g02-E19","v141-b-g01-E12"]}],"theta":[{"parameter_id":"v141-c-R003-theta-r_i","symbol":"r_i","meaning":"Reservation price per unit of energy set by RU i; a fixed input to the RU's best response to the announced price p_t in this coordination stage.","value":{"kind":"symbolic","number_value":null,"text_value":"r_i"},"unit":null,"indices":["i"],"evidence_ids":["v141-b-g02-E11","v141-b-g02-E17","v141-b-g02-E13"]},{"parameter_id":"v141-c-R003-theta-alpha_i","symbol":"α_i","meaning":"Reluctance parameter of RU i measuring its unwillingness to share ES; a fixed coefficient in the RU utility used in the best response.","value":{"kind":"symbolic","number_value":null,"text_value":"α_i"},"unit":null,"indices":["i"],"evidence_ids":["v141-b-g02-E11","v141-b-g02-E17"]},{"parameter_id":"v141-c-R003-theta-b_i","symbol":"b_i","meaning":"Maximum shareable ES space of RU i, defined in the source as s_i^{cap} - d_i; it is the upper bound of the RU's ES-sharing strategy.","value":{"kind":"symbolic","number_value":null,"text_value":"s_i^{cap} - d_i"},"unit":null,"indices":["i"],"evidence_ids":["v141-b-g01-E08","v141-b-g02-E17"]},{"parameter_id":"v141-c-R003-theta-p_t_min","symbol":"p_t^{min}","meaning":"Lower bound on the auctioneer's price signal; identified in the source as the Vickrey price or second-highest reservation price for the participating RUs.","value":{"kind":"symbolic","number_value":null,"text_value":"p_t^{min} (Vickrey price)"},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g01-E35","v141-b-g02-E13"]},{"parameter_id":"v141-c-R003-theta-p_t_max","symbol":"p_t^{max}","meaning":"Upper bound on the auctioneer's price signal; identified in the source as the highest reservation price among the participating RUs at the supply-demand intersection.","value":{"kind":"symbolic","number_value":null,"text_value":"p_t^{max}"},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g01-E35","v141-b-g02-E13"]}],"phi":[{"constraint_id":"v141-c-R003-C001","kind":"procedural","role":"core","statement":"The auction price p_t announced by the auctioneer coordinates participating RUs' choices of ES space to share, with each RU choosing within [0, b_i] to maximize its own utility. Scope: The Stackelberg payment rule for joint ES sharing within the smart community, including its application within each time slot.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["pricing.local","coordination.price_signal"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g01-E04","v141-b-g02-E13","v141-b-g02-E17","v141-b-g02-E34"]},{"constraint_id":"v141-c-R003-C002","kind":"mathematical","role":"core","statement":"For each participating RU i, the ES amount x_i chosen in response to the announced price p_t lies in [0, b_i] and maximizes U_i(x_i) = (p_t - r_i)x_i - α_i x_i^2; equivalently, x_i^* is the argmax of that utility over 0 ≤ x_i ≤ b_i. Scope: Stackelberg price-signal coordination for participating RUs in the community ES-sharing auction; the time-varying extension applies the same per-slot response.","expression":"x_i^* = \\arg\\max_{0 \\le x_i \\le b_i} \\left[(p_t - r_i)x_i - \\alpha_i x_i^2\\right]","formalization_origin":"source","template_id":null,"members":["pricing.local","coordination.price_signal"],"variable_refs":["v141-c-R003-x-p_t","v141-c-R003-x-x_i"],"parameter_refs":["v141-c-R003-theta-r_i","v141-c-R003-theta-alpha_i","v141-c-R003-theta-b_i"],"evidence_ids":["v141-b-g02-E19","v141-b-g02-E13","v141-b-g02-E11","v141-b-g02-E17"]},{"constraint_id":"v141-c-R003-C003","kind":"mathematical","role":"supporting","statement":"The auctioneer's announced price p_t is restricted to the interval [p_t^{min}, p_t^{max}], where p_t^{min} is the Vickrey price (second-highest reservation price) and p_t^{max} the highest reservation price for participating RUs. Scope: Stackelberg payment-rule price strategy in the community ES-sharing auction.","expression":"p_t \\in [p_t^{min}, p_t^{max}]","formalization_origin":"source","template_id":null,"members":["pricing.local","coordination.price_signal"],"variable_refs":["v141-c-R003-x-p_t"],"parameter_refs":["v141-c-R003-theta-p_t_min","v141-c-R003-theta-p_t_max"],"evidence_ids":["v141-b-g02-E13","v141-b-g01-E35"]},{"constraint_id":"v141-c-R003-C004","kind":"mathematical","role":"supporting","statement":"Equation (11) reports the RU best response for a given price p_t as x_i^* = (p_t - r_i)/(2α_i). Scope: RU best response in the Stackelberg payment rule; the bounded argmax in C002 retains the source's [0, b_i] constraint.","expression":"x_i^* = \\frac{p_t - r_i}{2\\alpha_i}","formalization_origin":"source","template_id":null,"members":["pricing.local","coordination.price_signal"],"variable_refs":["v141-c-R003-x-p_t","v141-c-R003-x-x_i"],"parameter_refs":["v141-c-R003-theta-r_i","v141-c-R003-theta-alpha_i"],"evidence_ids":["v141-b-g02-E17","v141-b-g02-E11"]}],"pi":[{"evidence_id":"v141-b-g01-E04","location":{"location_id":"src-441686b1ee-p02-c2r4__v141-a-M01-participation","page":2,"printed_page":null,"section":"II. State-of-the-Art","anchor_text":"ge revenues for stakeholders [28], [29]. However, one similar- or- ity among most of the above menti","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-02.png","occurrence_role":"definition"},"source_text":"In this regard, considering the potential benefits of ES sharing, as discussed in [10], this paper investigates the case in which the SFCs in a smart community are allowed to share some fraction of the ESs owned by the RUs through a third party such as an auctioneer or a community representative."},{"evidence_id":"v141-b-g02-E13","location":{"location_id":"src-441686b1ee-p06-c1r2__v141-a-M01-pricing","page":6,"printed_page":null,"section":"IV-B. Payment Rule","anchor_text":"as = {{{1, 2, . . . , J −1}, {Auctioneer}}, {Ui}i∈{1,2,...,J−1}, {Xi}i∈{1,2,...,J−1}, Z, pt}, (5) wh","equation_id":"(5)","figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"\\Gamma = {{{1, 2, ..., J −1}, {Auctioneer}}, {U_i}_{i∈{1,2,...,J−1}}, {X_i}_{i∈{1,2,...,J−1}}, Z, p_t}, (5) which consists of: i) the set of RUs {1, 2, ..., J −1} participating in the auction scheme and the auctioneer; ii) the utility U_i that each RU i reaps from choosing a suitable strategy x_i in response to the price p_t announced by the auctioneer; iii) the strategy set X_i of each RU i ∈ {1, 2, ..., J −1}; iv) the average cost savings Z incurred to each SFC m ∈ {1, 2, ..., K−1} from the strategy chosen by the auctioneer, and v) the strategy p_t ∈ [p_t^{min}, p_t^{max}] of the auctioneer."},{"evidence_id":"v141-b-g02-E17","location":{"location_id":"src-441686b1ee-p07-c1r1__v141-a-M01-pricing","page":7,"printed_page":null,"section":"IV-B. Payment Rule","anchor_text":"1468 δ2Ui \u003c 0. Hence, for any Alto xi, ∀i ∈{1, 2, . . . , J −1}, i.e., δx2i price pt ∈[pmint , pmaxt","equation_id":"(11)","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"δ^2U_i/δx_i^2 \u003c 0. Hence, for any xi, ∀i ∈ {1, 2, ..., J −1}, i.e., for any price p_t ∈ [p_t^{min}, p_t^{max}], each RU will have a unique x_i, which will be chosen from a bounded range [0, b_i] and maximize U_i. To this end, first we note that the amount of ES x_i^* at which the RU i achieves its maximum utility in response to a price p_t can be obtained from (6), x_i^* = (p_t − r_i)/(2α_i). (11)"},{"evidence_id":"v141-b-g02-E34","location":{"location_id":"src-441686b1ee-p09-c2r3__v141-a-M01-pricing","page":9,"printed_page":null,"section":"IV-F. Adaptation to Time-Varying Case","anchor_text":"the proposed modiﬁed auction scheme studied in Section IV 0) can be adopted in each time slot t = 1,","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-09.png","occurrence_role":"restatement"},"source_text":"To this end, for the modeled x_{i,t} ∀i ∈ N and q_{m,t} ∀m ∈ M, the proposed modified auction scheme studied in Section IV can be adopted in each time slot t = 1, 2, ..., T with a view to maximize (19) and (20) ∀t. It is important to note that the reservation price vector r_i of each RU i ∈ N and the bidding price vector a_m of each SFC m ∈ M can be modeled through any existing time-varying pricing schemes such as time-of-use price [3]. Now, p_t^* = [p_{t,1}^*, p_{t,2}^*, ..., p_{t,T}^*] and x^* = [x_1^*, x_2^*, ..., x_N^*] constitute the solutions of the proposed modified auction scheme in a time-varying condition, if the x^* comprises the solution vector of all ES spaces shared by the participating RUs in each time slot t = 1, 2, ..., T for the auction price vector p_t^*. Further, all the auction rules adopted in each time slot of the proposed time-varying case will be similar to the rules discussed in Section IV. Hence, the solution of the proposed modified auction scheme for a time-varying environment also possesses the incentive compatibility and individual rationality properties for each time slot."},{"evidence_id":"v141-b-g01-E08","location":{"location_id":"src-441686b1ee-p03-c2r2__v141-a-M01-bidding","page":3,"printed_page":null,"section":"III. System Model","anchor_text":"on ks in he n- ng nd Fig. 1. The fraction of the ES capacity that an RU i is willing to share with t","equation_id":"(1)","figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"formula"},"source_text":"The battery capacity of each RU $i \\in \\mathcal{N}$ is $s_i^{\\mathrm{cap}}$, and each RU $i$ wants to put $x_i$ fraction of its ES in the market to share with the SFCs, where $x_i \\le b_i = \\left(s_i^{\\mathrm{cap}} - d_i\\right).$ Here, $b_i$ is the maximum amount of battery space that the RU can share with the SFCs if the cost-benefit tradeoff for the sharing is attractive for it. $d_i$ is the amount of ES that the RU does not want to share, but rather uses for its own needs, e.g., to run the essential loads in the future if there is any electricity disruption within the RU or if the price of electricity is very high."},{"evidence_id":"v141-b-g01-E12","location":{"location_id":"src-441686b1ee-p04-c1r3__v141-a-M01-bidding","page":4,"printed_page":null,"section":"IV. Auction Based ES Ownership","anchor_text":"are willing to share with the SFCs. The amount of xi is deter- na mined by the trade-off between the","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"The amount of $x_i$ is determined by the trade-off between the economic benefits that the RU $i$ expects to obtain from giving the SFCs the joint ownership of its ES device and the associated reluctance $\\alpha_i$ of the RU for such sharing. Therefore, for a given set of bids $a_m, \\forall m$ and storage requirements $q_m, \\forall m$ by the SFCs, the maximum amount of ES $x_i$ that each RU $i$ will decide to put into sharing is strongly affected by the trading price $p_t$ and the reluctance parameter$^{4}$ $\\alpha_i$ of each RU $i \\in \\mathcal{N}$ during the sharing process."},{"evidence_id":"v141-b-g01-E35","location":{"location_id":"src-441686b1ee-p05-c2r2__v141-a-M01-pricing","page":5,"printed_page":null,"section":"IV-B. Payment Rule","anchor_text":"p p y y no participating agents in the auction mechanism will cheat once the payment and allocation ","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"We note that the intersection of the demand and supply curves demonstrates the highest reservation price $p_t^{\\max}$ for the participating $J - 1$ RUs. According to the Vickrey auction mechanism [14], the auction price for sharing the ES devices would be the second highest reservation price, i.e., the Vickrey price, which will be indicated as $p_t^{\\min}$ hereinafter."},{"evidence_id":"v141-b-g01-E36","location":{"location_id":"src-441686b1ee-p05-c2r3__v141-a-M01-pricing","page":5,"printed_page":null,"section":"IV-B. Payment Rule","anchor_text":"the Vickrey price, which will be indicated as pmint hereinafter. ed However, we note that this secon","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"However, we note that this second highest price might not be considerably beneficial for all the participating RUs in the auction scheme. In contrast, if $p_t$ is set to $p_t = p_t^{\\max}$, the price could be detrimental for some of the SFCs. Therefore, to make the auction scheme attractive and beneficial to all the participating RUs and, at the same time, to be cost effective for all the SFCs, we strike a balance between $p_t^{\\max}$ and $p_t^{\\min}$. To do so, we propose a scheme for deciding on both the auction price $p_t$ and the amount of ESs $x_i$ that RUs will put into the market for sharing according to $p_t$. In particular, we propose a Stackelberg game between the auctioneer, which decides on the auction price $p_t$ to maximize the average cost savings to the SFCs as well as satisfying their desirable needs of ESs, and the RUs, which decide on the vector containing the amounts of ES $\\mathbf{x} = [x_1, x_2, \\ldots, x_{J-1}]$ that they would like to put into the market for sharing such that their benefits are maximized."},{"evidence_id":"v141-b-g02-E11","location":{"location_id":"src-441686b1ee-p06-c1r2__v141-a-M01-pricing","page":6,"printed_page":null,"section":"IV-B. Payment Rule","anchor_text":"as = {{{1, 2, . . . , J −1}, {Auctioneer}}, {Ui}i∈{1,2,...,J−1}, {Xi}i∈{1,2,...,J−1}, Z, pt}, (5) wh","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"formula"},"source_text":"Ui(xi) = (pt −ri)xi −αixi^2, xi ≤bi, (6) where, αi is the reluctance parameter of RU i, and ri is the reservation price set by RU i."},{"evidence_id":"v141-b-g02-E19","location":{"location_id":"src-441686b1ee-p07-c2r1__v141-a-M01-validation","page":7,"printed_page":null,"section":"IV-C. Algorithm for Payment","anchor_text":"IEEE TRANSACTIONS ON SMART GRID, VOL. 7, NO. 3, MAY 2016 ny Algorithm 1 Algorithm for SLMFSG to Reac","equation_id":"(13)","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"example"},"source_text":"Algorithm 1 Algorithm for SLMFSG to Reach the SE 1: Initialization: p_t^* = p_t^{min}, Z^*=0. 2: for Auction price p_t from p_t^{min} to p_t^{max} do 3: for Each RU i ∈ {1, 2, ..., (J −1)} do 4: RU i adjusts its amount of ES x_i to share according to x_i^* = arg max_{0≤x_i≤b_i} [(p_t−r_i)x_i − α_i x_i^2]. (13) 5: end for 6: The auctioneer computes the average cost savings to SFCs Z = (Σ_{m=1}^{K−1}(a_m −p_t)/(K−1)) Σ_{i=1}^{J−1} x_i^*. (14) 7: if Z ≥ Z^* then 8: The auctioneer record the desirable price and maximum average cost savings p_t^* = p_t, Z^*=Z. (15) 9: end if 10: end for The SE (x^*, p_t^*) is achieved."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-bidding","v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-participation","v141-a-M01-pricing","v141-a-M01-validation"],"extras":{"decision_anchor":"coordination.price_signal","graph_fact_supports":[[{"evidence_id":"v141-b-g02-E13","quote":"the utility U_i that each RU i reaps from choosing a suitable strategy x_i in response to the price p_t announced by the auctioneer"},{"evidence_id":"v141-b-g02-E17","quote":"each RU will have a unique x_i, which will be chosen from a bounded range [0, b_i] and maximize U_i. To this end, first we note that the amount of ES x_i^* at which the RU i achieves its maximum utility in response to a price p_t can be obtained from (6)"},{"evidence_id":"v141-b-g01-E04","quote":"the SFCs in a smart community are allowed to share some fraction of the ESs owned by the RUs through a third party such as an auctioneer or a community representative."},{"evidence_id":"v141-b-g02-E34","quote":"Further, all the auction rules adopted in each time slot of the proposed time-varying case will be similar to the rules discussed in Section IV."}]],"C2_formalization":{"graph_sha256":"faee746b9f4f1100cbb58c5b302e3d0c3329e0643a12611602c63558ad891785","applicability":"formalized","reason":"The frozen price-signal coordination relation is formalized with source equations (5), (11), and (13). C001 is preserved as the procedural coordination statement; C002 formalizes the bounded RU best response to the announced auction price, C003 formalizes the auctioneer's price interval, and C004 retains the source's printed closed-form best response. B evidence remains unreviewed.","bindings":[{"object_id":"v141-c-R003-x-p_t","node_ids":["coordination.price_signal","pricing.local"],"edge_ids":["v141-c-R003-E001"],"rationale":"p_t is the auctioneer's announced price; coordination.price_signal is the frozen node for that price signal, and pricing.local is the pricing-rule node linked to it by edge E001."},{"object_id":"v141-c-R003-x-x_i","node_ids":["coordination.price_signal","pricing.local"],"edge_ids":["v141-c-R003-E001"],"rationale":"x_i is the RU's ES-space response to the announced price p_t; this choice is governed by the price-signal relation and its pricing constraint, represented by the two nodes linked in E001."},{"object_id":"v141-c-R003-theta-r_i","node_ids":["pricing.local","coordination.price_signal"],"edge_ids":["v141-c-R003-E001"],"rationale":"r_i is a fixed reservation-price input to the RU response in the pricing rule; it affects the comparison with p_t under the E001 link."},{"object_id":"v141-c-R003-theta-alpha_i","node_ids":["pricing.local","coordination.price_signal"],"edge_ids":["v141-c-R003-E001"],"rationale":"α_i is a fixed reluctance parameter in the RU utility used in the best response formalized under the E001 price-response link."},{"object_id":"v141-c-R003-theta-b_i","node_ids":["pricing.local","coordination.price_signal"],"edge_ids":["v141-c-R003-E001"],"rationale":"b_i is the fixed upper bound on x_i in the RU's strategy set, used by the price-response relation linked by E001."},{"object_id":"v141-c-R003-theta-p_t_min","node_ids":["pricing.local","coordination.price_signal"],"edge_ids":["v141-c-R003-E001"],"rationale":"p_t^{min} bounds the auctioneer's price signal in the pricing rule linked to coordination.price_signal by E001."},{"object_id":"v141-c-R003-theta-p_t_max","node_ids":["pricing.local","coordination.price_signal"],"edge_ids":["v141-c-R003-E001"],"rationale":"p_t^{max} bounds the auctioneer's price signal in the pricing rule linked to coordination.price_signal by E001."},{"object_id":"v141-c-R003-C002","node_ids":["pricing.local","coordination.price_signal"],"edge_ids":["v141-c-R003-E001"],"rationale":"Formalizes the bounded RU best response to p_t; it binds the announced price signal to the RU ES choice under the frozen E001 link."},{"object_id":"v141-c-R003-C003","node_ids":["pricing.local","coordination.price_signal"],"edge_ids":["v141-c-R003-E001"],"rationale":"Formalizes the price interval constraining p_t in the pricing rule linked to the price signal by E001."},{"object_id":"v141-c-R003-C004","node_ids":["pricing.local","coordination.price_signal"],"edge_ids":["v141-c-R003-E001"],"rationale":"Formalizes the source's printed closed-form best response as a supporting expression for the same E001 price-response link."}],"revision_requests":[]}},"quarantined_references":[]}});
